@namespace sv_c65cde6ecf5d453e92da872fe81c9f68.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application steps">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var step = i + 1;
        var cssClass = GetStepClass(step);
        var isClickable = CompletedSteps.Contains(step) && step != CurrentStep;

        <button class="step @cssClass"
                disabled="@(!isClickable)"
                @onclick="() => OnStepClicked.InvokeAsync(step)"
                aria-current="@(step == CurrentStep ? "step" : null)">
            <span class="step-number">
                @if (CompletedSteps.Contains(step) && step != CurrentStep)
                {
                    <span class="checkmark">✓</span>
                }
                else
                {
                    @step
                }
            </span>
            <span class="step-label">@StepNames[i]</span>
        </button>

        @if (i < StepNames.Length - 1)
        {
            <span class="step-connector @(CompletedSteps.Contains(step) ? "completed" : "")"></span>
        }
    }
</nav>

@code {
    private static readonly string[] StepNames =
        ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter] public HashSet<int> CompletedSteps { get; set; } = [];
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private string GetStepClass(int step)
    {
        if (step == CurrentStep) return "active";
        if (CompletedSteps.Contains(step)) return "completed";
        return "pending";
    }
}

@namespace sv_c65cde6ecf5d453e92da872fe81c9f68.Components.Pages.Apply

<div class="work-entry-editor">
    <div class="entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (ShowRemove)
        {
            <button type="button" class="btn-remove" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Company Name *</label>
            <input type="text" @bind="Entry.Company" @bind:event="oninput" placeholder="Company name" />
        </div>
        <div class="form-group">
            <label>Job Title *</label>
            <input type="text" @bind="Entry.Title" @bind:event="oninput" placeholder="Job title" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" @bind="Entry.StartDate" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" @bind="Entry.EndDate" disabled="@Entry.IsCurrent" />
            <label class="checkbox-label">
                <input type="checkbox" @bind="Entry.IsCurrent" @bind:after="HandleCurrentChanged" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea @bind="Entry.Description" @bind:event="oninput" rows="3" placeholder="Describe your responsibilities..."></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private void HandleCurrentChanged()
    {
        if (Entry.IsCurrent)
        {
            Entry.EndDate = null;
        }
    }
}

@namespace sv_c65cde6ecf5d453e92da872fe81c9f68.Components.Pages.Apply

<div class="reference-editor">
    <div class="entry-header">
        <h4>Reference @(Index + 1)</h4>
        @if (ShowRemove)
        {
            <button type="button" class="btn-remove" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Name *</label>
            <input type="text" @bind="Reference.Name" @bind:event="oninput" placeholder="Reference name" />
        </div>
        <div class="form-group">
            <label>Relationship *</label>
            <input type="text" @bind="Reference.Relationship" @bind:event="oninput" placeholder="e.g., Former Manager" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Email *</label>
            <input type="email" @bind="Reference.Email" @bind:event="oninput" placeholder="email@example.com" />
        </div>
        <div class="form-group">
            <label>Phone</label>
            <input type="tel" @bind="Reference.Phone" @bind:event="oninput" placeholder="(555) 000-0000" />
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public ReferenceModel Reference { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
}

