@namespace sv_c65cde6ecf5d453e92da872fe81c9f68.Components.Pages.Apply

<div class="step-content">
    <h2>Personal Information</h2>

    @if (!string.IsNullOrEmpty(errorMessage))
    {
        <div class="validation-error">@errorMessage</div>
    }

    <div class="form-group">
        <label>Full Name *</label>
        <input type="text" @bind="Model.FullName" @bind:event="oninput" placeholder="John Doe" />
    </div>

    <div class="form-group">
        <label>Email *</label>
        <input type="email" @bind="Model.Email" @bind:event="oninput" placeholder="john@example.com" />
        @if (isValidatingEmail)
        {
            <span class="field-status">Validating email...</span>
        }
    </div>

    <div class="form-group">
        <label>Phone *</label>
        <input type="tel" @bind="Model.Phone" @bind:event="oninput" placeholder="(555) 000-0000" />
    </div>

    <div class="form-group">
        <label>Address *</label>
        <textarea @bind="Model.Address" @bind:event="oninput" rows="2" placeholder="Street, City, State, ZIP"></textarea>
    </div>

    <div class="step-actions">
        <span></span>
        <button class="btn-primary" @onclick="HandleNext" disabled="@isValidatingEmail">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public IApplicationService ApplicationService { get; set; } = default!;

    private string? errorMessage;
    private bool isValidatingEmail;

    private async Task HandleNext()
    {
        errorMessage = null;

        if (string.IsNullOrWhiteSpace(Model.FullName))
        {
            errorMessage = "Full name is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Model.Email))
        {
            errorMessage = "Email is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Model.Phone))
        {
            errorMessage = "Phone is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Model.Address))
        {
            errorMessage = "Address is required.";
            return;
        }

        isValidatingEmail = true;
        try
        {
            var isValid = await ApplicationService.ValidateEmailAsync(Model.Email);
            if (!isValid)
            {
                errorMessage = "Please enter a valid email address.";
                return;
            }
        }
        finally
        {
            isValidatingEmail = false;
        }

        await OnNext.InvokeAsync();
    }
}

