@namespace sv_c65cde6ecf5d453e92da872fe81c9f68.Components.Pages.Apply

<div class="step-content">
    <h2>Cover Letter</h2>

    @if (!string.IsNullOrEmpty(errorMessage))
    {
        <div class="validation-error">@errorMessage</div>
    }

    <div class="form-group">
        <label>Write your cover letter</label>
        <textarea class="cover-letter-input"
                  @bind="CoverLetter"
                  @bind:event="oninput"
                  @bind:after="NotifyChanged"
                  rows="12"
                  maxlength="@MaxLength"
                  placeholder="Tell us why you're a great fit for this role..."></textarea>
        <div class="char-count @(CoverLetter.Length > MaxLength ? "over-limit" : "")">
            @CoverLetter.Length / @MaxLength characters
        </div>
    </div>

    <div class="step-actions">
        <button class="btn-outline" @onclick="OnBack">Back</button>
        <button class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    private const int MaxLength = 2000;

    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<string> CoverLetterChanged { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }

    private string? errorMessage;

    private async Task NotifyChanged()
    {
        await CoverLetterChanged.InvokeAsync(CoverLetter);
    }

    private async Task HandleNext()
    {
        errorMessage = null;

        if (string.IsNullOrWhiteSpace(CoverLetter))
        {
            errorMessage = "Please write a cover letter.";
            return;
        }

        if (CoverLetter.Length > MaxLength)
        {
            errorMessage = $"Cover letter must be {MaxLength} characters or fewer.";
            return;
        }

        await OnNext.InvokeAsync();
    }
}

