@namespace sv_c65cde6ecf5d453e92da872fe81c9f68.Components.Pages.Apply

<div class="step-content">
    @if (IsSubmitted)
    {
        <div class="submission-confirmation">
            <div class="success-icon">✓</div>
            <h2>Application Submitted!</h2>
            <p>Your application has been received. Your application ID is:</p>
            <div class="application-id">#@ApplicationId</div>
            <p>Please save this ID for your records.</p>
        </div>
    }
    else
    {
        <h2>Review & Submit</h2>
        <p class="step-description">Please review your application before submitting.</p>

        @if (!string.IsNullOrEmpty(errorMessage))
        {
            <div class="validation-error">@errorMessage</div>
        }

        <div class="review-section">
            <div class="review-header">
                <h3>Personal Information</h3>
                <button class="btn-link" @onclick='() => OnEditSection.InvokeAsync(1)'>Edit</button>
            </div>
            <dl class="review-fields">
                <dt>Name</dt><dd>@Personal.FullName</dd>
                <dt>Email</dt><dd>@Personal.Email</dd>
                <dt>Phone</dt><dd>@Personal.Phone</dd>
                <dt>Address</dt><dd>@Personal.Address</dd>
            </dl>
        </div>

        <div class="review-section">
            <div class="review-header">
                <h3>Work History</h3>
                <button class="btn-link" @onclick='() => OnEditSection.InvokeAsync(2)'>Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-work-entry">
                    <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                    <div class="review-dates">
                        @(entry.StartDate?.ToString("MMM yyyy") ?? "N/A") –
                        @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                    </div>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p class="review-description">@entry.Description</p>
                    }
                </div>
            }
        </div>

        <div class="review-section">
            <div class="review-header">
                <h3>References</h3>
                <button class="btn-link" @onclick='() => OnEditSection.InvokeAsync(3)'>Edit</button>
            </div>
            @foreach (var r in References)
            {
                <div class="review-reference">
                    <strong>@r.Name</strong> — @r.Relationship
                    <div>@r.Email @(!string.IsNullOrWhiteSpace(r.Phone) ? $"· {r.Phone}" : "")</div>
                </div>
            }
        </div>

        <div class="review-section">
            <div class="review-header">
                <h3>Cover Letter</h3>
                <button class="btn-link" @onclick='() => OnEditSection.InvokeAsync(4)'>Edit</button>
            </div>
            <p class="review-cover-letter">@CoverLetter</p>
        </div>

        <div class="step-actions">
            <button class="btn-outline" @onclick="OnBack">Back</button>
            <button class="btn-primary btn-submit" @onclick="HandleSubmit" disabled="@isSubmitting">
                @(isSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Personal { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkEntryModel> WorkEntries { get; set; } = default!;
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public bool IsSubmitted { get; set; }
    [Parameter] public int ApplicationId { get; set; }
    [Parameter] public EventCallback<int> OnEditSection { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }

    private bool isSubmitting;
    private string? errorMessage;

    private async Task HandleSubmit()
    {
        errorMessage = null;
        isSubmitting = true;

        try
        {
            await OnSubmit.InvokeAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

arguments.file_text:
@page "/apply"
@rendermode InteractiveServer
@namespace sv_c65cde6ecf5d453e92da872fe81c9f68.Components.Pages.Apply
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="currentStep"
                   CompletedSteps="completedSteps"
                   OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 1:
            <PersonalInfoStep Model="personalInfo"
                              ApplicationService="ApplicationService"
                              OnNext="() => CompleteAndAdvance(1)" />
            break;
        case 2:
            <WorkHistoryStep Entries="workEntries"
                             OnBack="() => currentStep = 1"
                             OnNext="() => CompleteAndAdvance(2)" />
            break;
        case 3:
            <ReferencesStep References="references"
                            OnBack="() => currentStep = 2"
                            OnNext="() => CompleteAndAdvance(3)" />
            break;
        case 4:
            <CoverLetterStep @bind-CoverLetter="coverLetter"
                             OnBack="() => currentStep = 3"
                             OnNext="() => CompleteAndAdvance(4)" />
            break;
        case 5:
            <ReviewStep Personal="personalInfo"
                        WorkEntries="workEntries"
                        References="references"
                        CoverLetter="@coverLetter"
                        IsSubmitted="isSubmitted"
                        ApplicationId="applicationId"
                        OnEditSection="GoToStep"
                        OnBack="() => currentStep = 4"
                        OnSubmit="HandleSubmit" />
            break;
    }
</div>

@code {
    private int currentStep = 1;
    private HashSet<int> completedSteps = [];
    private bool isSubmitted;
    private int applicationId;

    private PersonalInfoModel personalInfo = new();
    private List<WorkEntryModel> workEntries = [new()];
    private List<ReferenceModel> references = [new(), new()];
    private string coverLetter = "";

    private void CompleteAndAdvance(int step)
    {
        completedSteps.Add(step);
        currentStep = step + 1;
    }

    private void GoToStep(int step)
    {
        if (completedSteps.Contains(step) || step == currentStep)
        {
            currentStep = step;
        }
    }

    private async Task HandleSubmit()
    {
        var application = new JobApplication(
            new PersonalInfo(personalInfo.FullName, personalInfo.Email, personalInfo.Phone, personalInfo.Address),
            new WorkHistory(workEntries.Select(e => new WorkEntry(
                e.Company, e.Title, e.StartDate ?? DateTime.MinValue, e.IsCurrent ? null : e.EndDate, e.Description
            )).ToList()),
            references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
            coverLetter
        );

        applicationId = await ApplicationService.SubmitApplicationAsync(application);
        isSubmitted = true;
    }
}

/* Application Form Layout */
.application-form {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem 1rem;
}

.application-form h1 {
    text-align: center;
    margin-bottom: 2rem;
    color: #1a1a2e;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    padding: 1rem 0;
    gap: 0;
}

.step-indicator .step {
    display: flex;
    flex-direction: column;
    align-items: center;
    background: none;
    border: none;
    cursor: default;
    padding: 0.25rem 0.5rem;
    min-width: 80px;
    transition: opacity 0.2s;
}

.step-indicator .step:not(:disabled) {
    cursor: pointer;
}

.step-indicator .step:not(:disabled):hover .step-number {
    transform: scale(1.1);
}

.step-number {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.9rem;
    margin-bottom: 0.35rem;
    transition: all 0.2s;
}

.step.active .step-number {
    background: #4361ee;
    color: #fff;
}

.step.completed .step-number {
    background: #2ecc71;
    color: #fff;
}

.step.pending .step-number {
    background: #e0e0e0;
    color: #999;
}

.checkmark {
    font-size: 1rem;
}

.step-label {
    font-size: 0.75rem;
    color: #666;
    text-align: center;
    white-space: nowrap;
}

.step.active .step-label {
    color: #4361ee;
    font-weight: 600;
}

.step.completed .step-label {
    color: #2ecc71;
}

.step-connector {
    flex: 0 0 40px;
    height: 2px;
    background: #e0e0e0;
    margin-bottom: 1.2rem;
}

.step-connector.completed {
    background: #2ecc71;
}

/* Step Content */
.step-content {
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 2rem;
}

.step-content h2 {
    margin-top: 0;
    margin-bottom: 0.5rem;
    color: #1a1a2e;
}

.step-description {
    color: #666;
    margin-bottom: 1.5rem;
}

/* Forms */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 600;
    margin-bottom: 0.3rem;
    color: #333;
    font-size: 0.9rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea,
.cover-letter-input {
    width: 100%;
    padding: 0.6rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 6px;
    font-size: 0.95rem;
    font-family: inherit;
    transition: border-color 0.2s;
    box-sizing: border-box;
}

.form-group input:focus,
.form-group textarea:focus,
.cover-letter-input:focus {
    outline: none;
    border-color: #4361ee;
    box-shadow: 0 0 0 3px rgba(67, 97, 238, 0.1);
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.4rem;
    font-weight: 400 !important;
    margin-top: 0.4rem;
    font-size: 0.85rem !important;
    cursor: pointer;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

.field-status {
    font-size: 0.8rem;
    color: #4361ee;
    font-style: italic;
}

/* Validation */
.validation-error {
    background: #fee;
    color: #c0392b;
    border: 1px solid #e74c3c;
    border-radius: 6px;
    padding: 0.75rem 1rem;
    margin-bottom: 1rem;
    font-size: 0.9rem;
}

/* Entry editors */
.work-entry-editor,
.reference-editor {
    border: 1px solid #e8e8e8;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
    background: #fafafa;
}

.entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.entry-header h4 {
    margin: 0;
    color: #444;
}

/* Buttons */
.step-actions {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-top: 1.5rem;
    padding-top: 1rem;
    border-top: 1px solid #eee;
}

.btn-primary {
    background: #4361ee;
    color: #fff;
    border: none;
    padding: 0.7rem 2rem;
    border-radius: 6px;
    font-size: 0.95rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.2s;
}

.btn-primary:hover:not(:disabled) {
    background: #3651d4;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-outline {
    background: #fff;
    color: #4361ee;
    border: 2px solid #4361ee;
    padding: 0.6rem 1.5rem;
    border-radius: 6px;
    font-size: 0.95rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s;
}

.btn-outline:hover {
    background: #f0f3ff;
}

.btn-secondary {
    background: none;
    color: #4361ee;
    border: 1px dashed #4361ee;
    padding: 0.5rem 1rem;
    border-radius: 6px;
    font-size: 0.9rem;
    cursor: pointer;
    margin-bottom: 1rem;
    transition: background 0.2s;
}

.btn-secondary:hover {
    background: #f0f3ff;
}

.btn-remove {
    background: none;
    color: #e74c3c;
    border: 1px solid #e74c3c;
    padding: 0.3rem 0.75rem;
    border-radius: 4px;
    font-size: 0.8rem;
    cursor: pointer;
    transition: all 0.2s;
}

.btn-remove:hover {
    background: #fee;
}

.btn-link {
    background: none;
    border: none;
    color: #4361ee;
    cursor: pointer;
    font-size: 0.9rem;
    text-decoration: underline;
